//! Contract tests against vectors produced by the real C++ headers.
//!
//! `tests/vectors.txt` is generated by `python -I rust/tests/transport_vectors.py --write`,
//! which compiles `build/vc-transport-vectors/gen.cpp` against the actual
//! `proto/vc_wire.h`, `common/crc32.h` and `common/fnv1a.h`. Regenerating it is the
//! authoritative cross-check; these tests run without needing the C++ toolchain.
//!
//! The same file also drives a real scrambled reassembly scenario (out-of-order packets,
//! one bad CRC, one duplicate), so the Rust engine is exercised with bytes produced by
//! the C++ implementation, not by itself.

use vc_transport::{
    Config, Geometry, HEADER_LEN, Header, IgnoreReason, PushOutcome, Reassembler, fragments,
};

const VECTORS: &str = include_str!("vectors.txt");

struct PacketLine {
    kind: &'static str,
    frame_id: u32,
    seq: u16,
    total: u16,
    len: usize,
    crc: u32,
    flags: u8,
    pattern: u8,
    qpc_ns: u64,
    payload: Vec<u8>,
}

fn unhex(text: &str) -> Vec<u8> {
    assert_eq!(text.len() % 2, 0, "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

fn parse_header(line: &str) -> (Header, [u8; 28]) {
    let fields: Vec<&str> = line.split_whitespace().collect();
    assert_eq!(fields[0], "header");
    let header = Header {
        magic: vc_transport::MAGIC,
        frame_id: fields[1].parse().unwrap(),
        seq: fields[2].parse().unwrap(),
        total: fields[3].parse().unwrap(),
        qpc_ns: fields[4].parse().unwrap(),
        payload_crc: fields[5].parse().unwrap(),
        payload_len: fields[6].parse().unwrap(),
        flags: fields[7].parse().unwrap(),
        pattern: fields[8].parse().unwrap(),
    };
    let mut bytes = [0u8; 28];
    bytes.copy_from_slice(&unhex(fields[9]));
    (header, bytes)
}

fn parse_packets() -> Vec<PacketLine> {
    VECTORS
        .lines()
        .filter(|line| {
            line.starts_with("packet ") || line.starts_with("badcrc ") || line.starts_with("dup ")
        })
        .map(|line| {
            let fields: Vec<&str> = line.split_whitespace().collect();
            PacketLine {
                kind: fields[0],
                frame_id: fields[1].parse().unwrap(),
                seq: fields[2].parse().unwrap(),
                total: fields[3].parse().unwrap(),
                len: fields[4].parse().unwrap(),
                crc: u32::from_str_radix(fields[5], 16).unwrap(),
                flags: fields[6].parse().unwrap(),
                pattern: fields[7].parse().unwrap(),
                qpc_ns: fields[8].parse().unwrap(),
                payload: unhex(fields[9]),
            }
        })
        .collect()
}

fn parse_checksum(prefix: &str) -> Vec<(Vec<u8>, u64)> {
    VECTORS
        .lines()
        .filter_map(|line| {
            let fields: Vec<&str> = line.split_whitespace().collect();
            if fields.len() != 3 || fields[0] != prefix {
                return None;
            }
            let payload = if fields[1] == "-" {
                Vec::new()
            } else {
                unhex(fields[1])
            };
            let value = u64::from_str_radix(fields[2], 16).unwrap();
            Some((payload, value))
        })
        .collect()
}

#[test]
fn cpp_checksum_vectors_match() {
    let crcs = parse_checksum("crc32");
    assert!(crcs.len() >= 3);
    for (payload, expected) in crcs {
        assert_eq!(
            vc_transport::checksum::crc32(&payload) as u64,
            expected,
            "CRC32 mismatch on {} bytes",
            payload.len()
        );
    }
    let fnvs = parse_checksum("fnv64");
    assert!(fnvs.len() >= 3);
    for (payload, expected) in fnvs {
        assert_eq!(
            vc_transport::checksum::fnv1a64(&payload),
            expected,
            "FNV mismatch on {} bytes",
            payload.len()
        );
    }
}

#[test]
fn cpp_header_bytes_match_frozen_layout() {
    let line = VECTORS
        .lines()
        .find(|line| line.starts_with("header "))
        .expect("header vector");
    let (header, bytes) = parse_header(line);
    assert_eq!(header.encode(), bytes);
    assert_eq!(Header::parse(&bytes).unwrap(), header);
    assert_eq!(HEADER_LEN, 28);
}

#[test]
fn cpp_geometry_matches_rust_math() {
    let mut seen = 0;
    for line in VECTORS.lines().filter(|line| line.starts_with("geometry ")) {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let width: u32 = fields[1].parse().unwrap();
        let height: u32 = fields[2].parse().unwrap();
        let frame_bytes: usize = fields[3].parse().unwrap();
        let mtu: usize = fields[4].parse().unwrap();
        let payload_max: usize = fields[5].parse().unwrap();
        let total: u16 = fields[6].parse().unwrap();
        let last: usize = fields[7].parse().unwrap();
        let geometry = Geometry::new(width, height).unwrap();
        assert_eq!(geometry.frame_bytes(), frame_bytes);
        assert_eq!(vc_transport::payload_max_for_mtu(mtu).unwrap(), payload_max);
        assert_eq!(
            vc_transport::packet_count(frame_bytes, payload_max).unwrap(),
            total
        );
        assert_eq!(
            vc_transport::payload_len_at(total - 1, total, frame_bytes, payload_max),
            last
        );
        seen += 1;
    }
    assert_eq!(seen, 2);
}

#[test]
fn rust_fragmentation_reproduces_cpp_packets() {
    let packets = parse_packets();
    let geometry = Geometry::new(64, 64).unwrap();
    let mut frame = vec![0u8; geometry.frame_bytes()];
    for packet in packets.iter().filter(|p| p.kind == "packet") {
        let offset = packet.seq as usize * 1458;
        frame[offset..offset + packet.len].copy_from_slice(&packet.payload);
    }
    let expected_hash = VECTORS
        .lines()
        .find(|line| line.starts_with("frame "))
        .map(|line| u64::from_str_radix(line.split_whitespace().nth(3).unwrap(), 16).unwrap())
        .unwrap();
    assert_eq!(vc_transport::checksum::fnv1a64(&frame), expected_hash);

    let generated: Vec<_> = fragments(
        &frame,
        77,
        vc_transport::fragment::FragmentConfig {
            payload_max: 1458,
            qpc_ns: 424242,
            pattern: 4,
        },
    )
    .unwrap()
    .collect();
    assert_eq!(
        generated.len(),
        packets.iter().filter(|p| p.kind == "packet").count()
    );
    let mut expected: Vec<&PacketLine> = packets.iter().filter(|p| p.kind == "packet").collect();
    expected.sort_by_key(|packet| packet.seq);
    for (part, packet) in generated.iter().zip(expected) {
        assert_eq!(part.header.frame_id, packet.frame_id);
        assert_eq!(part.header.seq, packet.seq);
        assert_eq!(part.header.total, packet.total);
        assert_eq!(part.header.payload_len as usize, packet.len);
        assert_eq!(part.header.payload_crc, packet.crc);
        assert_eq!(part.header.flags, packet.flags);
        assert_eq!(part.header.pattern, packet.pattern);
        assert_eq!(part.header.qpc_ns, packet.qpc_ns);
        assert_eq!(part.payload, packet.payload.as_slice());
    }
}

#[test]
fn reassembly_matches_cpp_scrambled_stream() {
    let packets = parse_packets();
    let config = Config::new(Geometry::new(64, 64).unwrap(), 1500).unwrap();
    assert_eq!(config.payload_max, 1458);
    assert_eq!(config.total, 5);
    let mut reassembler = Reassembler::new(config).unwrap();

    let mut completed = Vec::new();
    let mut now = 0u64;
    for packet in &packets {
        // C++ packets carry the CRC it computed; the `badcrc` line flips one bit.
        assert_eq!(
            vc_transport::checksum::crc32(&packet.payload) == packet.crc,
            packet.kind != "badcrc",
            "vector classification"
        );
        now += 1_000;
        let header = Header {
            magic: vc_transport::MAGIC,
            frame_id: packet.frame_id,
            seq: packet.seq,
            total: packet.total,
            qpc_ns: packet.qpc_ns,
            payload_crc: packet.crc,
            payload_len: packet.len as u16,
            flags: packet.flags,
            pattern: packet.pattern,
        };
        let outcome = reassembler.push_packet_at(header, &packet.payload, None, now);
        match outcome {
            PushOutcome::Completed(frame) => completed.push(frame),
            PushOutcome::Ignored(IgnoreReason::BadCrc) => {
                assert_eq!(packet.kind, "badcrc")
            }
            PushOutcome::Ignored(IgnoreReason::Duplicate) => assert_eq!(packet.kind, "dup"),
            PushOutcome::Accepted => assert_eq!(packet.kind, "packet"),
            other => panic!("unexpected outcome for {}: {other:?}", packet.kind),
        }
    }

    assert_eq!(completed.len(), 1);
    let frame = &completed[0];
    let expected_hash = VECTORS
        .lines()
        .find(|line| line.starts_with("frame "))
        .map(|line| u64::from_str_radix(line.split_whitespace().nth(3).unwrap(), 16).unwrap())
        .unwrap();
    assert_eq!(frame.frame_id, 77);
    assert_eq!(frame.hash(), expected_hash);
    assert_eq!(frame.hash_hex(), format!("{expected_hash:016x}"));

    let stats = reassembler.stats();
    assert_eq!(stats.complete, 1);
    assert_eq!(stats.crc_errors, 1);
    assert_eq!(stats.duplicate, 1);
    assert_eq!(stats.packets_lost, 1);
    assert_eq!(stats.dropped, 0);
    assert_eq!(
        stats.packets_recv,
        packets.iter().filter(|p| p.kind != "badcrc").count() as u64
    );
    assert_eq!(reassembler.inflight_frames(), 0);
    assert_eq!(reassembler.rseg_summary().samples, 1);
}

#[test]
fn ethernet_wrapper_roundtrips_cpp_header() {
    let packets = parse_packets();
    let packet = &packets[0];
    let header = Header {
        magic: vc_transport::MAGIC,
        frame_id: packet.frame_id,
        seq: packet.seq,
        total: packet.total,
        qpc_ns: packet.qpc_ns,
        payload_crc: packet.crc,
        payload_len: packet.len as u16,
        flags: packet.flags,
        pattern: packet.pattern,
    };
    let fragment = vc_transport::Fragment {
        header,
        payload: &packet.payload,
    };
    let mut ethernet = vec![0u8; 14 + 28 + packet.len];
    let written = vc_transport::write_ethernet([0xAA; 6], [0xBB; 6], &fragment, &mut ethernet)
        .expect("space");
    assert_eq!(written, ethernet.len());

    let mut reassembler = Reassembler::new(
        Config::new(Geometry::new(64, 64).unwrap(), 1500)
            .unwrap()
            .with_source_mac(Some([0xBB; 6])),
    )
    .unwrap();
    assert!(matches!(
        reassembler.push_ethernet(&ethernet),
        PushOutcome::Accepted | PushOutcome::Completed(_)
    ));
    assert_eq!(reassembler.stats().packets_recv, 1);

    ethernet[6] ^= 1;
    assert_eq!(
        reassembler.push_ethernet(&ethernet),
        PushOutcome::Ignored(IgnoreReason::OtherSource)
    );
}
